std::uint64_t mix(std::uint64_t x){x+=UINT64_C(0x9e3779b97f4a7c15);x=(x^(x>>30))*UINT64_C(0xbf58476d1ce4e5b9);x=(x^(x>>27))*UINT64_C(0x94d049bb133111eb);return x^(x>>31);}
std::size_t draw(std::mt19937_64& rng,std::size_t n){const auto bound=std::uint64_t(n),threshold=(std::uint64_t(0)-bound)%bound;std::uint64_t value;do{value=rng();}while(value<threshold);return static_cast<std::size_t>(value%bound);}
double finiteWide(long double value){if(!std::isfinite(value)||std::abs(value)>std::numeric_limits<double>::max())throw Error(PENTA_NUMERIC_DOMAIN,"Bootstrap statistic or summary exceeds finite binary64.");return static_cast<double>(value);}
double builtin(std::vector<double>& samples,const std::string& name){
    if(name=="min")return *std::min_element(samples.begin(),samples.end());
    if(name=="max")return *std::max_element(samples.begin(),samples.end());
    long double mean=0;for(auto x:samples)mean+=static_cast<long double>(x);mean/=samples.size();if(name=="mean")return finiteWide(mean);
    if(name=="median"){std::sort(samples.begin(),samples.end());const auto m=samples.size()/2;return samples.size()%2?samples[m]:std::midpoint(samples[m-1],samples[m]);}
    long double sum=0;if(name=="rms"){for(auto x:samples)sum+=static_cast<long double>(x)*x;return finiteWide(std::sqrt(sum/samples.size()));}
    require(name=="variance"||name=="stddev","Bootstrap statistic must be mean,median,stddev,variance,min,max,rms or a prepared native callback.");require(samples.size()>=2,"Sample variance/stddev bootstrap requires at least two values.");for(auto x:samples){const long double d=x-mean;sum+=d*d;}const auto v=sum/(samples.size()-1);return finiteWide(name=="stddev"?std::sqrt(v):v);
}
